from datetime import datetime, timedelta, timezone
from types import SimpleNamespace
import unittest

import uniclubs_user


NOW = datetime(2026, 11, 15, 10, 0)
OWNER = 'profile-owner-a'
OTHER = 'profile-owner-b'
EVENT_ID = 'uniclubs:event-a'


def event(**changes):
    """Return the minimal domain attributes needed by the private state machine."""
    values = {'event_id': EVENT_ID, 'start': NOW + timedelta(days=1),
              'end': NOW + timedelta(days=1, hours=2), 'can_confirm': True}
    values.update(changes)
    return SimpleNamespace(**values)


class UniClubsUserTests(unittest.TestCase):
    """Verify private state independently for each generated profile owner."""

    def setUp(self):
        """Create an isolated private store without touching any on-disk database."""
        self.connection = uniclubs_user.get_connection(':memory:')
        self.addCleanup(self.connection.close)
        uniclubs_user.init_db(self.connection)
        self.event = event()

    def save(self, action, rating=None, now=NOW, owner=OWNER, activity=None, user_id=1):
        """Apply an action with explicit overrides while keeping test calls readable."""
        return uniclubs_user.save_interaction(
            self.connection, owner, user_id, activity or self.event, action, rating, now=now)

    def attend(self, owner=OWNER, user_id=1):
        """Confirm and attend one event using a clock strictly after its ending."""
        self.save('confirm', owner=owner, user_id=user_id)
        ended = self.event.end + timedelta(seconds=1)
        return self.save('attended', now=ended, owner=owner, user_id=user_id)

    def test_changed_or_cancelled_schedule_cannot_enable_feedback(self):
        """A display-only estimated end or changed program must not authorize attendance/rating."""
        self.save('confirm')
        ended = self.event.end + timedelta(days=2)
        for changes in ({'end_is_estimated': True}, {'source_cancelled': True},
                        {'is_multi_day': lambda: True}):
            with self.subTest(changes=changes):
                changed = event(**changes)
                with self.assertRaises(ValueError):
                    self.save('attended', activity=changed, now=ended)
        self.assertEqual(uniclubs_user.get_interaction(
            self.connection, OWNER, EVENT_ID)['status'], 'confirmed')

    def test_empty_private_store_has_no_plans_favorites_or_revision(self):
        """Reading an untouched owner must return empty private state."""
        self.assertIsNone(uniclubs_user.get_interaction(self.connection, OWNER, EVENT_ID))
        self.assertEqual(uniclubs_user.list_interactions(self.connection, OWNER), [])
        self.assertEqual(uniclubs_user.get_favorites(self.connection, OWNER),
                         {'series': set(), 'club': set()})
        self.assertEqual(uniclubs_user.get_revision(self.connection, OWNER), 0)

    def test_same_event_is_isolated_between_profile_owners(self):
        """An identical public source ID must not share another profile's private plan."""
        first = self.save('confirm')
        self.assertIsNone(uniclubs_user.get_interaction(self.connection, OTHER, EVENT_ID))
        second = self.save('confirm', owner=OTHER, user_id=2)
        self.assertNotEqual(first['id'], second['id'])
        self.save('cancel')
        self.assertEqual(uniclubs_user.get_interaction(
            self.connection, OTHER, EVENT_ID)['status'], 'confirmed')

    def test_confirm_cancel_reconfirm_preserves_one_private_plan(self):
        """A canceled future event can be confirmed again without duplicating its plan."""
        first = self.save('confirm')
        with self.assertRaises(ValueError):
            self.save('confirm')
        self.save('cancel', now=NOW + timedelta(minutes=1))
        again = self.save('confirm', now=NOW + timedelta(minutes=2))
        self.assertEqual(first['id'], again['id'])
        self.assertEqual(again['status'], 'confirmed')
        self.assertNotEqual(first['confirmed_at'], again['confirmed_at'])
        self.assertEqual(len(uniclubs_user.list_interactions(self.connection, OWNER)), 1)

    def test_unavailable_or_started_source_cannot_be_newly_confirmed(self):
        """Missing, canceled or already-started source offers must not become new plans."""
        for activity in (event(can_confirm=False), event(start=NOW)):
            with self.subTest(activity=activity):
                with self.assertRaises(ValueError):
                    self.save('confirm', activity=activity)
        self.assertEqual(uniclubs_user.list_interactions(self.connection, OWNER), [])

    def test_existing_future_plan_can_be_cancelled_after_source_closes(self):
        """A changed source must not trap the user in a previously confirmed plan."""
        self.save('confirm')
        result = self.save('cancel', activity=event(can_confirm=False))
        self.assertEqual(result['status'], 'cancelled')

    def test_cancellation_after_start_is_rejected_without_changing_plan(self):
        """The existing time boundary still applies to source-specific cancellation."""
        first = self.save('confirm')
        with self.assertRaises(ValueError):
            self.save('cancel', now=self.event.start)
        self.assertEqual(uniclubs_user.get_interaction(self.connection, OWNER, EVENT_ID), first)

    def test_attendance_requires_confirmed_state_and_strictly_ended_time(self):
        """Attendance is available only for a confirmation after the actual event end."""
        with self.assertRaises(ValueError):
            self.save('attended', now=self.event.end + timedelta(seconds=1))
        self.save('confirm')
        with self.assertRaises(ValueError):
            self.save('attended', now=self.event.end)
        attended = self.save('attended', now=self.event.end + timedelta(seconds=1))
        self.assertEqual(attended['status'], 'attended')
        self.assertIsNotNone(attended['answered_at'])
        with self.assertRaises(ValueError):
            self.save('attended', now=self.event.end + timedelta(seconds=2))

    def test_effective_rating_changes_advance_only_the_current_owner_revision(self):
        """Repeated identical ratings must not invalidate the model repeatedly."""
        self.attend()
        ended = self.event.end + timedelta(minutes=1)
        first = self.save('rate', 4, now=ended)
        self.assertEqual(first['rating'], 4)
        self.assertEqual(uniclubs_user.get_revision(self.connection, OWNER), 1)
        self.save('rate', 4, now=ended)
        self.assertEqual(uniclubs_user.get_revision(self.connection, OWNER), 1)
        changed = self.save('rate', 5, now=ended)
        self.assertEqual(changed['rating'], 5)
        self.assertEqual(uniclubs_user.get_revision(self.connection, OWNER), 2)
        self.assertEqual(uniclubs_user.get_revision(self.connection, OTHER), 0)
        for rating in (0, 6, True, 4.5, '4', None):
            with self.subTest(rating=rating):
                with self.assertRaises(ValueError):
                    self.save('rate', rating, now=ended)
        self.assertEqual(uniclubs_user.get_revision(self.connection, OWNER), 2)
        self.assertEqual(uniclubs_user.get_interaction(
            self.connection, OWNER, EVENT_ID)['rating'], 5)

    def test_no_show_cannot_be_rated(self):
        """No-show feedback must remain outside attended-rating training examples."""
        self.save('confirm')
        ended = self.event.end + timedelta(seconds=1)
        self.save('not_attended', now=ended)
        with self.assertRaises(ValueError):
            self.save('rate', 4, now=ended)
        self.assertEqual(uniclubs_user.get_revision(self.connection, OWNER), 0)

    def test_invalid_inputs_leave_no_private_plans(self):
        """Reject invalid ownership, identifiers, actions and rating arguments before writes."""
        for changes in ({'owner': ''}, {'user_id': True}, {'user_id': 0},
                        {'activity': event(event_id=1)},
                        {'activity': event(event_id='legacy:event-a')},
                        {'now': NOW.replace(tzinfo=timezone.utc)},
                        {'rating': 4}):
            with self.subTest(changes=changes):
                with self.assertRaises(ValueError):
                    self.save('confirm', **changes)
        for action in ('unknown', [], {}):
            with self.subTest(action=action):
                with self.assertRaises(ValueError):
                    self.save(action)
        self.assertEqual(uniclubs_user.list_interactions(self.connection, OWNER), [])

    def test_favorites_are_idempotent_owner_scoped_and_source_scoped(self):
        """Favorite matching must distinguish local legacy IDs and other source/profile keys."""
        series = 'uniclubs-series:event-a'
        club = 'uniclubs-club:club-a'
        for enabled in (True, True):
            uniclubs_user.set_favorite(self.connection, OWNER, 'series', series, enabled)
        uniclubs_user.set_favorite(self.connection, OWNER, 'club', club, True)
        self.assertEqual(uniclubs_user.get_favorites(self.connection, OWNER),
                         {'series': {series}, 'club': {club}})
        self.assertEqual(uniclubs_user.get_favorites(self.connection, OTHER),
                         {'series': set(), 'club': set()})
        uniclubs_user.set_favorite(self.connection, OWNER, 'series', series, False)
        self.assertEqual(uniclubs_user.get_favorites(self.connection, OWNER)['series'], set())
        for kind, target, enabled in (('series', 'uniclubs-club:club-a', True),
                                      ('club', 1, True), ('other', club, True),
                                      ([], club, True), ({}, club, True),
                                      ('club', club, 1)):
            with self.subTest(kind=kind, target=target, enabled=enabled):
                with self.assertRaises(ValueError):
                    uniclubs_user.set_favorite(self.connection, OWNER, kind, target, enabled)

    def test_clear_owner_keeps_other_profiles_private_data(self):
        """A profile reset must delete only its own plans, favorites and revision state."""
        self.attend()
        self.save('rate', 5, now=self.event.end + timedelta(minutes=1))
        self.save('confirm', owner=OTHER, user_id=2)
        uniclubs_user.set_favorite(self.connection, OWNER, 'club', 'uniclubs-club:a', True)
        uniclubs_user.set_favorite(self.connection, OTHER, 'club', 'uniclubs-club:b', True)
        uniclubs_user.clear_owner(self.connection, OWNER)
        self.assertEqual(uniclubs_user.list_interactions(self.connection, OWNER), [])
        self.assertEqual(uniclubs_user.get_revision(self.connection, OWNER), 0)
        self.assertEqual(uniclubs_user.get_favorites(self.connection, OWNER),
                         {'series': set(), 'club': set()})
        self.assertEqual(len(uniclubs_user.list_interactions(self.connection, OTHER)), 1)
        self.assertEqual(uniclubs_user.get_favorites(self.connection, OTHER)['club'],
                         {'uniclubs-club:b'})

    def test_private_rows_store_identity_and_state_without_public_catalog_copy(self):
        """Personal state must reference the source instead of copying event metadata."""
        row = self.save('confirm')
        for field in ('title', 'start_utc', 'end_utc', 'description', 'source_url'):
            self.assertNotIn(field, row)
        self.assertEqual(row['event_id'], EVENT_ID)
        self.assertEqual(row['user_id'], 1)

    def test_owner_text_is_bound_data_not_sql(self):
        """Quotes in a private owner key must not alter schema or another profile's records."""
        owner = "profile'); DROP TABLE plans; --"
        result = self.save('confirm', owner=owner)
        self.assertEqual(result['owner'], owner)
        self.assertIsNone(uniclubs_user.get_interaction(self.connection, OWNER, EVENT_ID))
        self.assertEqual(len(uniclubs_user.list_interactions(self.connection, owner)), 1)


if __name__ == '__main__':
    unittest.main()
